import{_ as s,o,c as a,a2 as t}from"./chunks/framework.a6FUKr6c.js";const E=JSON.parse('{"title":"Memory repositories","description":"","frontmatter":{},"headers":[],"relativePath":"repositories/memory.md","filePath":"repositories/memory.md","lastUpdated":1795414261000}'),n={name:"repositories/memory.md"};function r(c,e,l,p,i,d){return o(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="memory-repositories" tabindex="-1">Memory repositories <a class="header-anchor" href="#memory-repositories" aria-label="Permalink to &quot;Memory repositories&quot;">​</a></h1><p>The memory repositories of <code>@chamvi/store-memory</code> keep every aggregate in one process, for development and tests: <code>MemoryRunRepository</code>, <code>MemoryStepRepository</code>, <code>MemoryCheckpointRepository</code>, <code>MemoryEffectRepository</code>, <code>MemoryArtifactRepository</code>, <code>MemoryStateRepository</code>, <code>MemoryStateDocumentRepository</code>, <code>MemoryLockRepository</code>, <code>MemoryIdempotencyRepository</code>, <code>MemoryAgentRevisionRepository</code>, <code>MemoryConnectionRepository</code> and <code>MemoryConversationRepository</code>, all on one <code>MemoryRegistry</code>. Build each service of <code>@chamvi/core</code> on its repository and pass it to <code>new Engine()</code>; <code>createTestEngine()</code> of <code>@chamvi/test-kit</code> builds all of it for tests, and <code>@chamvi/app</code> without <code>DATABASE_URL</code> does the same.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8EA7FF;">import</span><span style="color:#E3E5EA;"> { MemoryRegistry, MemoryRunRepository } </span><span style="color:#8EA7FF;">from</span><span style="color:#E7C58C;"> &#39;@chamvi/store-memory&#39;</span><span style="color:#E3E5EA;">;</span></span>
<span class="line"><span style="color:#8EA7FF;">import</span><span style="color:#E3E5EA;"> { RunService, systemClock } </span><span style="color:#8EA7FF;">from</span><span style="color:#E7C58C;"> &#39;@chamvi/core&#39;</span><span style="color:#E3E5EA;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8EA7FF;">const</span><span style="color:#E3E5EA;"> registry = </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> MemoryRegistry();</span></span>
<span class="line"><span style="color:#8EA7FF;">const</span><span style="color:#E3E5EA;"> runService = </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> RunService({ repository: </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> MemoryRunRepository({ registry }), clock: systemClock });</span></span></code></pre></div><p>The registry enforces the references the database&#39;s foreign keys do, both ways: a step, a checkpoint or a conversation turn of a run the registry does not hold is refused (the services throw <code>RunNotFoundError</code>), and a run or checkpoint bound to a conversation it does not hold is <code>EntityRelationError</code>. Build every repository on the same registry. The connection repository&#39;s fence reads the lock rows of its registry: build the lock service on a lock repository of the same registry. <code>MemoryConversationRepository</code> keeps its <code>items</code>, <code>notes</code> and <code>operations</code> child repositories in the registry too.</p><h2 id="how-it-keeps-the-contract" tabindex="-1">How it keeps the contract <a class="header-anchor" href="#how-it-keeps-the-contract" aria-label="Permalink to &quot;How it keeps the contract&quot;">​</a></h2><ul><li><strong>Copies:</strong> every value is stored and returned as a <code>structuredClone</code>.</li><li><strong>Atomicity:</strong> inside <code>transaction(fn)</code> every row read stays locked until the transaction ends (a lock cycle is <code>EntityDeadlockError</code>), so two callers never interleave between a read and its save in one process.</li><li><strong>Expiry:</strong> the services compare claims, keys and locks against <code>clock.now()</code> with the shared rule (expired at exactly <code>T + ttlMs</code>).</li></ul><p>Each repository passes the same port suite every other implementation must pass.</p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><ul><li>Tests, with a <code>ControllableClock</code> from <a href="/reference/test-kit"><code>@chamvi/test-kit</code></a> passed to the services and the engine.</li><li>Local development and scripts.</li><li>A single process where losing queued and waiting runs on restart is acceptable.</li></ul><div class="warning custom-block"><p class="custom-block-title">Not durable</p><p>Everything is gone with the process: queued runs, waiting approvals, checkpoints, recorded effects, agent state and artifacts. It also cannot be shared between replicas. Use the database repositories to survive restarts or to run more than one replica.</p></div><h2 id="in-tests" tabindex="-1">In tests <a class="header-anchor" href="#in-tests" aria-label="Permalink to &quot;In tests&quot;">​</a></h2><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8EA7FF;">const</span><span style="color:#E3E5EA;"> clock = </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> ControllableClock(</span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> Date(</span><span style="color:#E7C58C;">&#39;2026-01-01T00:00:00Z&#39;</span><span style="color:#E3E5EA;">));</span></span>
<span class="line"><span style="color:#8EA7FF;">const</span><span style="color:#E3E5EA;"> locks = </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> LockService({ repository: </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> MemoryLockRepository({ registry: </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> MemoryRegistry() }), clock });</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8EA7FF;">await</span><span style="color:#E3E5EA;"> locks.acquire(</span><span style="color:#E7C58C;">&#39;job&#39;</span><span style="color:#E3E5EA;">, </span><span style="color:#E7C58C;">&#39;replica-a&#39;</span><span style="color:#E3E5EA;">, </span><span style="color:#E7C58C;">1_000</span><span style="color:#E3E5EA;">); </span><span style="color:#80858F;">// a fencing token (a number)</span></span>
<span class="line"><span style="color:#8EA7FF;">await</span><span style="color:#E3E5EA;"> locks.acquire(</span><span style="color:#E7C58C;">&#39;job&#39;</span><span style="color:#E3E5EA;">, </span><span style="color:#E7C58C;">&#39;replica-b&#39;</span><span style="color:#E3E5EA;">, </span><span style="color:#E7C58C;">1_000</span><span style="color:#E3E5EA;">); </span><span style="color:#80858F;">// undefined, held by replica-a</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E3E5EA;">clock.advance(</span><span style="color:#E7C58C;">1_000</span><span style="color:#E3E5EA;">); </span><span style="color:#80858F;">// a lease expires at exactly T + ttlMs</span></span>
<span class="line"><span style="color:#8EA7FF;">await</span><span style="color:#E3E5EA;"> locks.acquire(</span><span style="color:#E7C58C;">&#39;job&#39;</span><span style="color:#E3E5EA;">, </span><span style="color:#E7C58C;">&#39;replica-b&#39;</span><span style="color:#E3E5EA;">, </span><span style="color:#E7C58C;">1_000</span><span style="color:#E3E5EA;">); </span><span style="color:#80858F;">// a higher token</span></span></code></pre></div>`,12)])])}const h=s(n,[["render",r]]);export{E as __pageData,h as default};
